name: Deploy Pastel to GitHub Pages
# Production trigger: keep Pages deployment tied to main changes. TTS v2 smoke uses live Supabase Edge Function.
on:
  push:
    branches: [main]
  workflow_dispatch:
permissions:
  contents: read
  pages: write
  id-token: write
concurrency:
  group: pages
  cancel-in-progress: true
jobs:
  deploy:
    runs-on: ubuntu-latest
    environment:
      name: github-pages
      url: ${{ steps.deployment.outputs.page_url }}
    steps:
      - uses: actions/checkout@v4
      - uses: actions/configure-pages@v5
        with:
          enablement: true
      - name: Fetch photorealistic Host candidate
        run: |
          mkdir -p assets
          curl -L --fail --retry 3 --retry-delay 2 \
            -o assets/pastel-host.glb \
            https://raw.githubusercontent.com/nirholas/three.ws/238ef6089554773f3485e13b8e463670ab5988d8/public/avatars/realistic-male.glb
          test -s assets/pastel-host.glb
          file assets/pastel-host.glb
      - name: Verify Host GLB structure
        run: |
          node -e "const fs=require('fs');const b=fs.readFileSync('assets/pastel-host.glb');if(b.readUInt32LE(0)!==0x46546c67)throw Error('invalid GLB');const j=JSON.parse(b.subarray(20,20+b.readUInt32LE(12)).toString().trim());const nodes=(j.nodes||[]).map(x=>x.name||'');const skins=j.skins||[];const anim=(j.animations||[]).map(x=>x.name||'');const head=nodes.find(n=>/head/i.test(n)&&!/head(?:top|end|tip)$/i.test(n));if(!skins.length||!head)throw Error('missing skeleton/head');console.log(JSON.stringify({skins:skins.length,bones:skins.reduce((n,s)=>n+(s.joints||[]).length,0),headBone:head,animations:anim},null,2));"
      - uses: actions/upload-pages-artifact@v4
        with:
          path: .
      - id: deployment
        uses: actions/deploy-pages@v4

      - name: Verify deployed Host audio + lipsync with Playwright
        env:
          PASTEL_PAGE_URL: ${{ steps.deployment.outputs.page_url }}
        run: |
          npm init -y >/dev/null 2>&1
          npm install --no-save playwright@1.55.0 >/dev/null 2>&1
          npx playwright install --with-deps chromium >/dev/null 2>&1
          cat > pastel-host-smoke.mjs <<'EOF'
          import { chromium } from "playwright";
          const url = process.env.PASTEL_PAGE_URL;
          if (!url) throw new Error("missing page_url");
          const browser = await chromium.launch({headless:true});
          const page = await browser.newPage();
          const tts = [];
          const pageErrors = [];
          page.on("pageerror", err => pageErrors.push(String(err?.message || err)));
          page.on("console", msg => { if (msg.type() === "error") pageErrors.push(msg.text()); });
          page.on("request", req => {
            if (req.url().includes("/functions/v1/pastel-tts-v2")) tts.push(req);
          });
          await page.goto(url, {waitUntil:"networkidle", timeout:60000});
          await page.waitForTimeout(3000);
          const boot = await page.evaluate(() => ({boot:window.__PASTEL_HOST_MODULE_BOOT__||null, verify:window.__PASTEL_HOST_VERIFY__||null, loadError:window.__PASTEL_HOST_LOAD_ERROR__||null}));
          if (boot.boot !== "started" && !boot.loadError) throw new Error("Host module never booted; pageErrors="+pageErrors.join(" | "));
          await page.waitForFunction(() => window.__PASTEL_HOST_VERIFY__?.headBone || window.__PASTEL_HOST_LOAD_ERROR__, null, {timeout:30000});
          const verify = await page.evaluate(() => window.__PASTEL_HOST_VERIFY__);
          if (verify?.loadError) throw new Error("Host runtime load failed: "+verify.loadError+"; pageErrors="+pageErrors.join(" | "));
          if (!verify.headBone) throw new Error("head bone missing");
          if (!verify.skeleton) throw new Error("skeleton missing");
          const buttons = await page.locator("#questions button").count();
          if (!buttons) throw new Error("question buttons missing");
          await page.evaluate(() => {
            window.__PASTEL_HOST_LIPSYNC_SAMPLES__ = [];
            const t = setInterval(() => {
              const x = window.__PASTEL_HOST_LIPSYNC_SAMPLE__?.();
              if (x) window.__PASTEL_HOST_LIPSYNC_SAMPLES__.push(x);
            }, 80);
            setTimeout(() => clearInterval(t), 5000);
          });
          const speakResult = await page.evaluate(async () => {
            const fn = window.__PASTEL_SPEAK__;
            if (typeof fn !== "function") return {type:typeof fn, result:null};
            try {
              const result = await fn("اختبار صوت المضيف في PASTEL.");
              return {type:"function", result:null};
            } catch (error) {
              return {type:"function", error:String(error?.message || error)};
            }
          });
          await page.waitForTimeout(250);
          await page.evaluate(() => window.PASTEL_HOST_LIPSYNC?.useText?.("اختبار حركة الشفاه العربية في PASTEL."));
          const directViseme = await page.evaluate(() => window.__PASTEL_HOST_VISEME_TEST__?.("viseme_aa"));
          if (!(directViseme?.matched > 0 && directViseme?.readBack > 0)) throw new Error("Direct Host viseme morph activation failed: "+JSON.stringify(directViseme));
          await page.waitForTimeout(650);
          const runtime = await page.evaluate(() => ({
            verify: window.__PASTEL_HOST_VERIFY__,
            speak: window.__PASTEL_SPEAK_DIAG__ || null,
            audio: window.PASTEL_AUDIO_LIPSYNC ? {
              mode: window.PASTEL_AUDIO_LIPSYNC.mode,
              connected: window.PASTEL_AUDIO_LIPSYNC.connected,
              analyser: window.PASTEL_AUDIO_LIPSYNC.analyser,
              source: window.PASTEL_AUDIO_LIPSYNC.source
            } : null,
            samples: window.__PASTEL_HOST_LIPSYNC_SAMPLES__ || []
          }));
          if (speakResult.type !== "function") throw new Error("PASTEL speak function missing: "+JSON.stringify(speakResult));
          if (speakResult.error) throw new Error("PASTEL speak rejected: "+speakResult.error);
          if (tts.length) throw new Error("remote TTS should be disabled for deterministic fallback; requests="+tts.length);
          if (!runtime.speak?.fallback) throw new Error("browser speech fallback was not selected: "+JSON.stringify(runtime.speak));
          if (runtime.speak?.fallbackMode !== "browser-speech+text-viseme") throw new Error("text-viseme fallback missing: "+JSON.stringify(runtime.speak));
          const nonzero = runtime.samples.some(s => (s.values?.length||0) + (s.jaw?.length||0) > 0);
          if (!(runtime.verify?.textVisemeActive > 0)) throw new Error("Host text-viseme did not activate any morph targets: "+JSON.stringify(runtime.verify));
          console.log(JSON.stringify({
            url,
            ttsRequests: tts.length,
            directViseme,
            analyserConnected: false,
            audioMode: runtime.verify.audioLipsync.mode,
            speechFallback: runtime.speak.fallback,
            fallbackMode: runtime.speak.fallbackMode,
            sampleCount: runtime.samples.length,
            nonzero,
            verify: runtime.verify
          }, null, 2));
          await browser.close();
          EOF
          node pastel-host-smoke.mjs

name: Normalize PASTEL source

on:
  push:
    branches:
      - feat/productize-pastel-fast

permissions:
  contents: write

jobs:
  normalize:
    if: github.actor != 'github-actions[bot]'
    runs-on: ubuntu-latest
    steps:
      - uses: actions/checkout@v4
      - name: Normalize escaped newlines and duplicate order handler
        run: |
          python - <<'PY'
          from pathlib import Path
          p = Path("index.html")
          s = p.read_text()
          s = s.replace("\\n", "\n")
          marker = 'const addOrderItem=document.getElementById("add-order-item");'
          first = s.find(marker)
          second = s.find(marker, first + len(marker)) if first >= 0 else -1
          if first >= 0 and second >= 0:
              end = s.find('const entry=document.getElementById("cinematic-entry");', second)
              block = """const addOrderItem=document.getElementById("add-order-item");
          addOrderItem?.addEventListener("click",()=>{
            const name=document.getElementById("order-item-name")?.value.trim();
            const quantity=Math.max(1,Number.parseInt(document.getElementById("order-item-qty")?.value||"1",10)||1);
            const status=document.getElementById("order-status");
            if(!name){status.textContent="اكتب اسم العنصر أولاً.";return}
            const item=orderState.items.find(x=>x.name===name);
            if(item)item.quantity+=quantity; else orderState.items.push({name,quantity});
            document.getElementById("order-item-name").value="";
            document.getElementById("order-item-qty").value="1";
            status.textContent="تمت إضافة العنصر إلى الطلب.";
            renderOrder();
          });
          """
              s = s[:first] + block + s[end:]
          p.write_text(s)
          PY
      - name: Commit normalized source
        run: |
          git config user.name "github-actions[bot]"
          git config user.email "41898282+github-actions[bot]@users.noreply.github.com"
          git add index.html
          git diff --cached --quiet && exit 0
          git commit -m "fix: normalize PASTEL runtime source"
          git push

